import sys

def main():
    input = sys.stdin.read
    data = input().split()
    if not data:
        return

    n = int(data[0])
    s = int(data[1])

    weights = [int(x) for x in data[2:2 + n]]

    bags = 1
    current_weight = 0

    for w in weights:
        if current_weight + w <= s:
            current_weight += w
        else:
            bags += 1
            current_weight = w

    print(bags)

if __name__ == '__main__':
    main()
